Ok, I have a work-around.  This is a small script you attach to your AnimationPlayer node that adds a "Merge Tracks" button to the inspector panel.  It fixes up the animation track paths, leveraging unique names when available.

```gd
@tool
extends AnimationPlayer

@export_tool_button("Merge Tracks", "AnimationPlayer") var merge_action = merge_tracks


func merge_tracks():
    print(self.name, " merging animation tracks:")
    print(get_animation_list())

    var anim_root: Node = get_node(root_node)
    for anim_name in get_animation_list():
        var anim: Animation = get_animation(anim_name)
        for track_idx in anim.get_track_count():
            var track_path: NodePath = anim.track_get_path(track_idx)
            var target: Node = anim_root.get_node(track_path)
            var names := anim_root.get_path_to(target, true).get_concatenated_names()
            var subnames := track_path.get_concatenated_subnames()
            var fixed_path := NodePath(names + ":" + subnames)
            if fixed_path == track_path:
                continue
            print(track_path, "-> ", fixed_path)
            anim.track_set_path(track_idx, fixed_path)

